import logo from './logo.svg';
import React, {Component} from 'react';
import { BrowserRouter, Switch, Route, NavLink } from 'react-router-dom';
import { Loader, Dimmer, Progress, Input, Button } from 'semantic-ui-react';

import Home from './components/Home.js';
import Page from './components/Page.js';
import Printable from './components/Printable.js';
// import Entry from './components/Entry.js';
// import WordBuilder from './components/WordBuilder.js';
// import SentenceBuilder from './components/SentenceBuilder.js';
// import Dialogues from './components/Dialogues.js';
// import Report from './components/Report.js';
// import TlingitMap from './components/Map.js';
// import Phrasebook from './components/Phrasebook.js';
// import Conversations from './components/Conversations.js';
// import Chinese from './components/constants/chinese.js';
import 'semantic-ui-css/semantic.min.css'
import './App.css';
import axios from 'axios';

export const API_URL = "http://localhost:5001";
// export const API_URL = "https://www.inupiaqonline.com/fastapi/";


let masterMedicalList = [{'id': '1', 'eTerm': 'Stigma', 'eDesc': 'Fear of being labeled or judged for seeking mental health support', 'yTerm': '', 'yDesc': "Tun'ernarqun", 'speakers': ['Tunriryuglunicangaknayukluniikayungcaquniumyualiurteńun'], 'resourceID': '1'}, {'id': '2', 'eTerm': 'Perceived Weakness', 'eDesc': 'Belief that asking for help is a sign of weakness or not being strong enough', 'yTerm': '', 'yDesc': 'Kemyukenricuklukuaryaraq', 'speakers': ["Ukverumalukuikayucalleqcirliqnaklukuwall'pinianaqniluku"], 'resourceID': '1'}, {'id': '3', 'eTerm': 'Lack of Trust', 'eDesc': 'Concerns about confidentiality and whether they can trust the counselor ', 'yTerm': '', 'yDesc': 'Ukvernailkiyaraq', 'speakers': ["Peng'garuteklukuallanunqanrutkesciigacaraqcaliukvernarquciaumyualiurutem."], 'resourceID': '1'}, {'id': '4', 'eTerm': 'Depression', 'eDesc': 'Persistent feelings of sadness, hopelessness, or a lack of interest in activities over an extended period of time', 'yTerm': '', 'yDesc': 'Umyuiqsaraq', 'speakers': ['Angniiquralleq/Aliayugturalleq', 'caviirutleq', "wall'ilagaucugyuyuilnguqak'anun"], 'resourceID': '2'}, {'id': '5', 'eTerm': 'Anxiety', 'eDesc': 'Excessive worry, fear, or panic attacks that impact daily life', 'yTerm': '', 'yDesc': 'Umyuarniurun', 'speakers': ['Umyuarniupiarluni', 'alinguurluni', "wall'kap'ianamagtuumalukuyuucia"], 'resourceID': '2'}, {'id': '6', 'eTerm': 'Relationship Issues', 'eDesc': 'Conflicts, communication problems, or difficulties in personal relationships', 'yTerm': '', 'yDesc': 'Aipaqucaram Nagutai/Arenqiallugutai', 'speakers': ['Umyuallgutkevkenateng', 'taringucuunateng', "wall'arenqiallugutengqerrlutengaipaqucaramun"], 'resourceID': '2'}, {'id': '7', 'eTerm': 'Stress', 'eDesc': 'Overwhelming pressure or tension that affects mental and physical health', 'yTerm': '', 'yDesc': 'Umyuarniuryaraq', 'speakers': ["Umyuartuuteksiyaallrancamekwall'umyuartusciigatellranumyuiqengevkarlukutemii-llunaulluvkangluku"], 'resourceID': '2'}, {'id': '8', 'eTerm': 'Trauma and PTSD', 'eDesc': 'Distress and emotional difficulties resulting from past traumatic experiences', 'yTerm': '', 'yDesc': 'Umyuam Akngiringallra cali PTSD-q', 'speakers': ['Arenqiallugutetumyuamun-llucaknaanarqellriittaigarrlutengakngirnaqluteng'], 'resourceID': '2'}, {'id': '9', 'eTerm': 'Grief and Loss', 'eDesc': 'Coping with the death of a loved one or other significant losses', 'yTerm': '', 'yDesc': 'Qilnganeryaraq/Qivrulleq cali Tamarilleq Kenkekngaminek', 'speakers': ["Nanikuanaqtuquigaqatakenkekngaitnekwall'allanekarcaqalrianektamariaqata"], 'resourceID': '2'}, {'id': '10', 'eTerm': 'Substance Abuse', 'eDesc': 'Struggles with alcohol, drugs, or other addictive behaviors', 'yTerm': '', 'yDesc': 'Caarrlugnek Aturpallalleq', 'speakers': ['Cakviurutaitaangam', "iinrurrluutwall'allat-llutaqesciigatnarqellriit"], 'resourceID': '2'}, {'id': '11', 'eTerm': 'Eating Disorders', 'eDesc': 'Concerns related to unhealthy eating habits, body image, and weight', 'yTerm': '', 'yDesc': 'Neqkatgun Umyuiqsaraq', 'speakers': ["Civuuratetassinrilngurteggunner'urallritgun", 'tememayuqellerkaanun', 'uqamaltacianun-llu'], 'resourceID': '2'}, {'id': '12', 'eTerm': 'Self-Esteem Issues', 'eDesc': 'Low self-worth, negative self-perception, or a lack of confidence', 'yTerm': '', 'yDesc': 'Ellminek Arenqiallugutet', 'speakers': ['Ellminekarcaqakevkenani', 'ayuqucinitangvacurlagluku', "wall'kemyukevkenani"], 'resourceID': '2'}, {'id': '13', 'eTerm': 'Sleep Disturbances', 'eDesc': 'Difficulty falling asleep, staying asleep, or experiencing restful sleep', 'yTerm': '', 'yDesc': 'Qavarciigacarat', 'speakers': ['Qavarciiganani', 'qavarturluni', "wall'qavakegciluni"], 'resourceID': '2'}, {'id': '14', 'eTerm': 'Anger Management', 'eDesc': 'Difficulty controlling anger and expressing it in a healthy way', 'yTerm': '', 'yDesc': 'Qenqercukaarallrem Auluksaraa', 'speakers': ['Qenqercukaarlunicaliallagunassinrakunancesciiganaku/qenertenrilkurcesciiganani'], 'resourceID': '2'}, {'id': '15', 'eTerm': 'Workplace Stress', 'eDesc': 'Challenges related to job satisfaction, burnout, or work-life balance', 'yTerm': '', 'yDesc': 'Caliviim Umyuarniurutai', 'speakers': ['Cakviurutet/Arenqiallugutettungiinuncaliaqegciyaraan', 'calilnguqercaram/caliaminekpuukaucaraq', "wall'caliaranyuucian-lluarenqigingnaqsaraan"], 'resourceID': '2'}, {'id': '16', 'eTerm': 'Parenting Challenges', 'eDesc': 'Difficulties in managing and navigating the responsibilities of parenthood', 'yTerm': '', 'yDesc': 'Angayuqauyaram Cakviurutai', 'speakers': ['Angayuqauyaramauluksaraicaperqelluki'], 'resourceID': '2'}, {'id': '17', 'eTerm': 'Loneliness and Isolation', 'eDesc': 'Feeling of being alone or disconnected from others', 'yTerm': '', 'yDesc': 'Angniitelleq Kiimetleq-llu', 'speakers': ["Kiimelngatleqwall'allanuntaringumanricuklukuarluni/avvingaluni"], 'resourceID': '2'}, {'id': '18', 'eTerm': 'Phobias', 'eDesc': 'Intense fears or aversions to specific objects or situations', 'yTerm': '', 'yDesc': 'Nangyaryugyarat', 'speakers': ["Cakneqalingutengqerrluniwall'nanikuanaklukicatiliitwall'nanikuanaklukinantellni"], 'resourceID': '2'}, {'id': '19', 'eTerm': 'Obsessive-Compulsive Disorder', 'eDesc': 'Intrusive, repetitive thought and compulsive behaviors', 'yTerm': '', 'yDesc': "Nangyutet/Naullutet Umyuamek Au͡g'arciigalnguut cali Cayullra Tukniluni (OCD)", 'speakers': ["Au͡g'arciiganani", 'umyuaqenrirciiganakicalicayullritukniluteng'], 'resourceID': '2'}, {'id': '20', 'eTerm': 'Bipolar Disorder', 'eDesc': 'Mood swings between depressive and manic states', 'yTerm': '', 'yDesc': 'Umyuiqsaraq', 'speakers': ['Umyuaremcimiqetaallraakuliignialiayugpagyaramcaliusvilluggluni'], 'resourceID': '2'}, {'id': '21', 'eTerm': 'Attention-Deficit/Hyperactivity Disorder', 'eDesc': 'Difficulty focusing, impulsivity, and hyperactivity', 'yTerm': '', 'yDesc': 'Umyuam Uitasciigatellran/Arulairciigatellran Nangyutiik/Naulluutiik', 'speakers': ['Murilkesciiganani', 'caqtaarluniumyuarturpailegmi', 'uitasciiganani-llu'], 'resourceID': '2'}, {'id': '22', 'eTerm': 'Suicidal Thoughts or Self-Harm', 'eDesc': 'Contemplating self-harm or having thoughts of suicide', 'yTerm': '', 'yDesc': "Umyuartuutekellra Ellminek Tuqucugluni wall' Ellminek Akngircugluni", 'speakers': ['Umyuarteqluniellminekakngirnaluniwall’umyuarteqluniellminekpitaqnaluni.'], 'resourceID': '2'}, {'id': '23', 'eTerm': 'Body Dysmorphic Disorder (BDD)', 'eDesc': 'Obsession with perceived flaws in physical appearance', 'yTerm': '', 'yDesc': 'Umyuam Nangyutii/Naulluutii Ikiukluku Temni', 'speakers': ['Ikiukuurlukutemiinayuqucia'], 'resourceID': '2'}, {'id': '24', 'eTerm': 'Panic Disorders', 'eDesc': 'Sudden and intense episodes of fear or panic', 'yTerm': '', 'yDesc': 'Umyuam Nangyutii/Naulluutii Kapiayaraq', 'speakers': ['Alqunaqkapialunicalituknilunialingellrawall’kapiallra'], 'resourceID': '2'}, {'id': '25', 'eTerm': 'Mood Swings', 'eDesc': 'Unpredictable changes in mood and emotional states', 'yTerm': '', 'yDesc': 'Umyuarem Cimiqetaallra ', 'speakers': ['Nallunaqlunicimillerkaaumyuarancaliumyuarteqsaraan'], 'resourceID': '2'}, {'id': '26', 'eTerm': 'Compulsive Behaviors', 'eDesc': 'Repeated actions performed to alleviate anxiety or stress', 'yTerm': '', 'yDesc': 'Umyuiqsaraq Caurarpallallermun', 'speakers': ["Pulengquurlukucallniavitengnaqlukuumyuarrlugunwall'arenqiallugun"], 'resourceID': '2'}, {'id': '27', 'eTerm': 'Personality Disorders', 'eDesc': 'Patterns of thought and behavior that deviate from social norms', 'yTerm': '', 'yDesc': 'Yuum Umyuaranun Nangyutet/Naulluutet', 'speakers': ['Umyuarturyaraacayaraa-lluayuqevkenaniyuutpiciryarait'], 'resourceID': '2'}, {'id': '28', 'eTerm': 'Coping with Life Transitions', 'eDesc': 'Difficulty adjusting to major life changes such as divorce, retirement, or relocation', 'yTerm': '', 'yDesc': 'Auluksaraa Yuucim Cimiryaraanun', 'speakers': ['Caperrsugluniyuucimicimillrinekukutunavvuyucaramek', 'calinriryaramek', "wall'nuninqigcaramek"], 'resourceID': '2'}, {'id': '29', 'eTerm': 'Cultural or Identity Issues', 'eDesc': 'Struggles related to cultural difference, discrimination, or self- identity', 'yTerm': '', 'yDesc': "Yuuyaraminek wall' Cauciminek Arenqiallugcaraq", 'speakers': ['Cakviurluniayuqenrilngurnekyuuyaranek', 'allakaukiyaranek', "wall'yuumkituucianek"], 'resourceID': '2'}, {'id': '30', 'eTerm': 'Social Anxiety', 'eDesc': 'Fear or discomfort in social situations', 'yTerm': '', 'yDesc': 'Yuut Avatiitni Uitallerkam Umyuarniurutii', 'speakers': ["Ancurturnaklukuwall'arenqialliurnaklukuyugyalrianiuitallerkaq"], 'resourceID': '2'}, {'id': '31', 'eTerm': 'Lack of Motivation', 'eDesc': 'Difficulty finding the drive or energy to pursue goals', 'yTerm': '', 'yDesc': 'Cayuumiicaraq', 'speakers': ['Caperrsuglunitengruvkenani-llucayullmiegmirutellerkaanek'], 'resourceID': '2'}, {'id': '32', 'eTerm': 'Chronic Pain', 'eDesc': 'Emotional challenges associated with persistent physical pain', 'yTerm': '', 'yDesc': 'Nangamcugcaraq', 'speakers': ['Avegteqlunitememinek-llunangtequurluni'], 'resourceID': '2'}, {'id': '33', 'eTerm': 'Lack of Direction', 'eDesc': "Feeling lost or uncertain about one's life path or purpose", 'yTerm': '', 'yDesc': 'Yuucimini Callerkani Nalluluku', 'speakers': ["Ciunerkaunaniwall'uunguciinaniyuucimieglertellerkaanekwall'yuuciqnayuklukuallminek"], 'resourceID': '2'}, {'id': '34', 'eTerm': 'Fear of Judgement', 'eDesc': 'Worry that the counselor will form negative opinions about them', 'yTerm': '', 'yDesc': 'Aaryugluni Cangaknayukluni', 'speakers': ["Peng'garrluniumyualiurtemuncangaknayukluni"], 'resourceID': '1'}, {'id': '35', 'eTerm': 'Cultural or Religious Beliefs', 'eDesc': 'Worry about how counseling aligns with cultural or religious values', 'yTerm': '', 'yDesc': "Yuuyaraq wall' Ukverumayaraq", 'speakers': ["Peng'garuteklukuqaillunumyualiurtetqalaruciyaraitanalqigingallrakekqanruyutaiyuuyaramwall'ukverumayaram"], 'resourceID': '1'}, {'id': '36', 'eTerm': 'Financial Constraints', 'eDesc': 'Worries about the cost of therapy and whether it is affordable', 'yTerm': '', 'yDesc': 'Akim Nagutai', 'speakers': ["Peng'gartaqluniakilitarkaanekassiringcangnaqlerminekcaliakilicugngallerminek"], 'resourceID': '1'}, {'id': '37', 'eTerm': 'Not Knowing Where to Start', 'eDesc': 'Feeling overwhelmed about how to begin discussing their concerns', 'yTerm': '', 'yDesc': 'Uunguciitnakluku Qaillun Ayagnillerkani', 'speakers': ["Amruyugluniqaillunayagnillerkaanekpeng'garutminekqanaallerkaminek"], 'resourceID': '1'}, {'id': '38', 'eTerm': 'Denial', 'eDesc': 'Reluctance to admit how serious their issues are or to acknowledge the need for help', 'yTerm': '', 'yDesc': 'Piciunritniyaraq', 'speakers': ["Arenqiallugucetengarcaqalriarunritnilukuwall'ciuniurpek'nakuikayuanarqellni"], 'resourceID': '1'}, {'id': '39', 'eTerm': 'Uncertainty about Effectiveness', 'eDesc': 'Doubts about whether counseling will be helpful or make a difference', 'yTerm': '', 'yDesc': 'Ikayuutngungaicuklukuarluku', 'speakers': ["Umyuaranikapucimavkenaniumyualiullerkaqikayuutnguciqellranekwall'cimircecugngaciiqellranekassitmun"], 'resourceID': '1'}, {'id': '40', 'eTerm': 'Fear of Emotional Pain', 'eDesc': 'Worry about revisiting and discussing painful or traumatic experiences', 'yTerm': '', 'yDesc': 'Umyuami Akngirtellerkaanek Alingluni', 'speakers': ["Civuuraklukiumyuaqenqigtellerkaiqanaateklerkai-lluakngirutekellniwall'picurlautekellni"], 'resourceID': '1'}, {'id': '41', 'eTerm': 'Lack of Time', 'eDesc': 'Concerns about fitting therapy session into a busy schedule', 'yTerm': ' ', 'yDesc': "Sass'arkiuraitellerkaq", 'speakers': ["Peng'garuteklukuumyualiullerkamisass'aitellerkaaqacigtenrilami"], 'resourceID': '1'}, {'id': '42', 'eTerm': 'Cognitive Dissonance', 'eDesc': 'Holding conflicting beliefs about the value of therapy ', 'yTerm': '', 'yDesc': 'Umyuartuutminek Arenqiayugluni', 'speakers': ['Umyuaranarenqikevkenakuarcaqauciaumyualiuryaram'], 'resourceID': '1'}, {'id': '43', 'eTerm': 'Fear of Change', 'eDesc': 'Worries about the potential changes that may result from therapy', 'yTerm': '', 'yDesc': 'Aaryugluni Cimillerkamun', 'speakers': ["Peng'garuteklukucimirnayuklukuallerkaniumyualiurraarluni"], 'resourceID': '1'}, {'id': '44', 'eTerm': 'Self-Stigma', 'eDesc': 'Internal negative attitutes toward seeking mental health help ', 'yTerm': '', 'yDesc': 'Ellminek Kasngukluni', 'speakers': ['Kasnguyugluniyuallerkaminekumyuamiikayungcallerkaanek'], 'resourceID': '1'}, {'id': '45', 'eTerm': 'Reluctance to Open Up', 'eDesc': 'Fear of being vulnerable or sharing personal feeling with a stranger', 'yTerm': '', 'yDesc': 'Civuuraluni Qanaallerkaminek Umyuartullerminek', 'speakers': ["Aaryuteklukuakngircetlerkaniwall'umyuartuutminekancillerkaminekallamunyugmun"], 'resourceID': '1'}, {'id': '46', 'eTerm': 'Minimization of Problems', 'eDesc': "Downplaying the significance of their concerns, thinking they are not 'bad enough' for therapy", 'yTerm': '', 'yDesc': 'Pinarqellriarunritniluki Arenqiallugutni', 'speakers': ['Arcaqalriarunritnilukiarenqiallugutni', "umyuarteqluniarenqiallugutni'pinarqellriarunricukluki'umyualiullerkamun"], 'resourceID': '1'}, {'id': '47', 'eTerm': 'Previous Negative Experiences', 'eDesc': 'Past encounters with unsupportive or unhelpful mental health professionals', 'yTerm': '', 'yDesc': 'Ciungani Ikayungcallra Assiqsaunani', 'speakers': ["Ciunganicingumastaitellruluniwall'ikayuutngullruvkenatengumyualiurtetcalistait"], 'resourceID': '1'}, {'id': '48', 'eTerm': 'Coping Strategies', 'eDesc': 'A belief that they can handle their issues on their own or through other means ', 'yTerm': '', 'yDesc': 'Arenqiallugtenricaram Ikayuutekai', 'speakers': ["Arenqiallugucetengellmeggnekauluksugnganilukiwall'allagunauluksugnganiluki"], 'resourceID': '1'}, {'id': '49', 'eTerm': 'Lack of Awareness', 'eDesc': 'Not recognizing the signs of mental health struggles or the potential benefits of counseling', 'yTerm': '', 'yDesc': "Ellangqessiyaagpek'nani", 'speakers': ["Elitaqumavkenakiumyuaminekcakviullniwall'ikayuutnguyugngallerkaanekumyualiuryaram"], 'resourceID': '1'}, {'id': '50', 'eTerm': 'Cultural Mistrust', 'eDesc': 'Distrust of mental health services due to cultural or historical factors', 'yTerm': '', 'yDesc': 'Yuuyaraq Kemyunailkelluku', 'speakers': ["Kemyukevkenakiumyuamekikayuriyaratyuuyaranipiteklukuwall'nutempiciryarat"], 'resourceID': '1'}, {'id': '51', 'eTerm': 'Fear of Dependency ', 'eDesc': 'Concerns about becoming dependent on therapy or the counselor ', 'yTerm': '', 'yDesc': 'Aaqluku Elisngaksautellerkani', 'speakers': ["Umyuarniurlunieliyagutellerkaminekumyualiuryaraqwall'umyualiurta"], 'resourceID': '1'}, {'id': '52', 'eTerm': 'Social Pressures', 'eDesc': 'External pressures or expectation that discourage seeking help', 'yTerm': '', 'yDesc': 'Yuut Tangvagluki Maligarucaraq', 'speakers': ["Yuutqanellritwall'neryuniurutaitcingumavkenakuikayungcallerkaq"], 'resourceID': '1'}, {'id': '53', 'eTerm': 'Happiness', 'eDesc': 'A bright emotional state characterized by joy, contentment, or satisfaction', 'yTerm': '', 'yDesc': 'Angniryaraq', 'speakers': ['Tanqigcesngananiumyuamtungiinunukutun', 'nunaniryuk', 'elluiyaraq', 'wall’assililuni'], 'resourceID': '3'}, {'id': '54', 'eTerm': 'Sadness', 'eDesc': 'A low emotional state characterized by feelings of sorrow, grief, or unhappiness', 'yTerm': '', 'yDesc': 'Angniicaraq', 'speakers': ['Umyuaranayuquciaaciqsigluniukutunilulliqsaraq', 'iluteqsaraq', 'wall’angniicaraq'], 'resourceID': '3'}, {'id': '55', 'eTerm': 'Anger', 'eDesc': 'An intense emotional response often associated with feelings of fear, displeasure, frustration, or offense', 'yTerm': '', 'yDesc': 'Qenerrneq', 'speakers': ['Tuknilriaumyuamayuquciaan’aqlunialingaqami', 'assilinritaqami', 'makugtaqami', 'wall’umyuaranallaringanritaqan'], 'resourceID': '3'}, {'id': '56', 'eTerm': 'Fear', 'eDesc': 'An emotional response to a perceived threat or danger, often accompanied by a sense of unease or anxiety. Can be based on real or imagined factors', 'yTerm': '', 'yDesc': 'Alingun', 'speakers': ['Umyuamnallunairyaraaellangaqanalingciraqatniwall’aarnarqellriim', 'amllerqunektapengqeraqluniarenqianamekwall’umyuarniurutmek.Avalitaitpiciuyugngaluniwall’piciuvkenateng'], 'resourceID': '3'}, {'id': '57', 'eTerm': 'Surprise', 'eDesc': 'A bried emotional state in response to something unexpected or suden', 'yTerm': '', 'yDesc': 'Alangaaq', 'speakers': ['Umyuamayuqliriqertellraumyuaqumanrilngurmekwall’alqunaqertellriamek'], 'resourceID': '3'}, {'id': '58', 'eTerm': 'Disgust', 'eDesc': 'A strong aversion or revulsion toward something unpleasant or offensive', 'yTerm': '', 'yDesc': 'Cumaciyugyaraq', 'speakers': ['Cakneqassikevkenakuwall’quinakilunicamekassinrilngurmekwall’canganarqellriamek'], 'resourceID': '3'}, {'id': '59', 'eTerm': 'Contempt', 'eDesc': 'An internal rejection and/or judgement toward someone/something which we perceive as being below our standards', 'yTerm': '', 'yDesc': ' Arrsakiyaraq', 'speakers': ['Ilumikun/umyuamikunnekaklukucali/wall’pinarqutlirlukukina/catangvaumalriaaciqsinrulukuwangkutni'], 'resourceID': '3'}, {'id': '60', 'eTerm': 'Interest', 'eDesc': 'A state of curiousity, engagement, or attention toward something stimulating or captivating', 'yTerm': '', 'yDesc': 'Paqnanaq', 'speakers': ['Paqnakluku', 'cumikluku', 'wall’murilkellukucaiillanarqellriawall’tangvagyunaqluni'], 'resourceID': '3'}, {'id': '61', 'eTerm': 'Boredom', 'eDesc': 'A feeling of weariness or dissatisfaction resulting from a lack of interest or stimulation', 'yTerm': '', 'yDesc': "Nunaniryugpek'nani", 'speakers': ['Cayuumiinaniwall’assilivkenanicucukenrilamiuwall’anglanakenrilamiu'], 'resourceID': '3'}, {'id': '62', 'eTerm': 'Love', 'eDesc': 'A deep affection and connection toward someone or something, often accompanied by care and concern ', 'yTerm': '', 'yDesc': 'Kenka', 'speakers': ['Yugmunwall’camuncakneqassikiluniaipaqsunakluku-llu', 'aulukuurlukupeng’garutekaqluku-llu'], 'resourceID': '3'}, {'id': '63', 'eTerm': 'Jealousy', 'eDesc': 'A comples emotional state invloving feeling of envy, insecurity, or possessiveness', 'yTerm': '', 'yDesc': 'Ciknakiyaraq', 'speakers': ['Capernarqellriaumyuartuyaraqmakutgunayariluni', 'ellminekpiyukevkenani', 'wall’cirlakluku'], 'resourceID': '3'}, {'id': '64', 'eTerm': 'Guilt', 'eDesc': 'A sense of remorse or self-reproach resulting from a belief that one has done something wrong ', 'yTerm': '', 'yDesc': 'Umyuarniuryaraq', 'speakers': ['Umyuarrluggluniwall’ellminekavalitekluniukverngamialartellruniluni'], 'resourceID': '3'}, {'id': '65', 'eTerm': 'Shame', 'eDesc': 'A strong feeling of embarrassment or disgrace, often linked to a perceived failure or moral violation', 'yTerm': '', 'yDesc': 'Kasngunaq', 'speakers': ['Tuknilriaayuquciqkasnguyugluniwall’umyuarrluggluni', 'piurteksaicukluniwall’narurciyukluninarurtarkaunrilngurmek'], 'resourceID': '3'}, {'id': '66', 'eTerm': 'Embarassment', 'eDesc': 'A temporary state of self-consiousness or awkwardness resulting from social situations', 'yTerm': '', 'yDesc': 'Takaryugyaraq', 'speakers': ['Takaryugluniyuutavatiintellerkaminek'], 'resourceID': '3'}, {'id': '67', 'eTerm': 'Confidence', 'eDesc': "A state of self-assurance and belief in one's abilities or judgements", 'yTerm': '', 'yDesc': 'Kemyunarqekiyaraq', 'speakers': ['Ellminekkemyukluniukvekluku-llupiyugngallniwall’pillerkiuryugngallni'], 'resourceID': '3'}, {'id': '68', 'eTerm': 'Pride', 'eDesc': 'A positive emotional state associated with a sense of accomplishment or satisfaction', 'yTerm': '', 'yDesc': 'Ukveraitnaq', 'speakers': ['Elluatuuluniumyuarturyaraqqaqicillerminekwall’cupumanaqluni'], 'resourceID': '3'}, {'id': '69', 'eTerm': 'Relaxation', 'eDesc': 'A calm and unstrained mental state often associated with a sense of ease or transquility', 'yTerm': '', 'yDesc': 'Qinuitneq', 'speakers': ['Umyuaqmenuinanicagnerpegnaniayuqlunielluilriatunwall’qinuinani'], 'resourceID': '3'}, {'id': '70', 'eTerm': 'Stress', 'eDesc': 'A state of mental or emotional strain resulting from challenging or adverse situations', 'yTerm': '', 'yDesc': 'Umyuarrlugnaq', 'speakers': ["Cakviurnarqellriitwall'alingnarqellriitiqungqertuqumyuamnangteqellranekwall'caknaanarqellranek"], 'resourceID': '3'}, {'id': '71', 'eTerm': 'Anxiety', 'eDesc': 'A heightened state of worry, apprehension, or unease often accompanied by physical symptoms', 'yTerm': '', 'yDesc': 'Umyuarniurun', 'speakers': ['Umyuarniussiyaagluni', 'ancurturluni', 'wall’arenqiayuglunitapeqlukitememaviranarqutai'], 'resourceID': '3'}, {'id': '72', 'eTerm': 'Depression', 'eDesc': 'A persistent and pervasive low mood characterized by feeling of sadness, hopelessness, and loss of interest', 'yTerm': '', 'yDesc': 'Umyuiqsaraq Aliayugpagluni', 'speakers': ['Taqsuunanicaliciuniurumanrilnguqumyuamayuquciaaliayuglunikesianek', 'manimalutengaliayugluni', 'neryuniurutaunani', 'ilagaucuumiirulluni-llu.'], 'resourceID': '3'}, {'id': '73', 'eTerm': 'Frustration', 'eDesc': 'A state of dissatisfaction and irritation resulting from obstacles or unmet desires ', 'yTerm': '', 'yDesc': 'Makugcaraq', 'speakers': ['Assilivkenanieqnayugluni-llucanekwall’piyullniunakeksailamiki'], 'resourceID': '3'}, {'id': '74', 'eTerm': 'Euphoria', 'eDesc': 'An intense and elevated mood characterized by feelings of extreme happiness and excitement ', 'yTerm': '', 'yDesc': 'Angniq', 'speakers': ['Tukniluniquyigluni-lluayuquciqangnipiarluniqiilerrluni-llu'], 'resourceID': '3'}, {'id': '75', 'eTerm': 'Apathy', 'eDesc': 'A lack of interest, enthusiasm, or motivation toward activities or life in general ', 'yTerm': '', 'yDesc': 'Cayuumiitelleq', 'speakers': ['Cayuumiinani', 'tengruvkenani', 'wall’ilagaucuumiinanicalrianunwall’yuucimun.'], 'resourceID': '3'}, {'id': '76', 'eTerm': 'Nostalgia', 'eDesc': 'A sentimental longing or affectionate remembrance of the past', 'yTerm': '', 'yDesc': 'Yuarnayugyaraq', 'speakers': ['Yuarnaklukuwall’umyuaqutkegcilukukinguneq.'], 'resourceID': '3'}, {'id': '77', 'eTerm': 'Helpless', 'eDesc': 'Lacking the ability or power to take action or make change; feeling unable to help oneself', 'yTerm': '', 'yDesc': 'Nanikuayaraq', 'speakers': ['Cacetuvkenaniwall’qaillunpisciigananiwall’cimirciiganani;ellminekikayurciigalnganani.'], 'resourceID': '3'}, {'id': '78', 'eTerm': 'Trapped', 'eDesc': 'Unable to escape from a situation or place; feeling confined or restricted, with limited options for movement or action', 'yTerm': '', 'yDesc': 'Kalivqinalriit', 'speakers': ['Ayagciigananicallminekwall’uitaviminek;itengqangananiwall’natvarciigalnganani', 'ayagvigkaawall’callraikgenani.'], 'resourceID': '3'}, {'id': '79', 'eTerm': 'Ambivalence', 'eDesc': 'Experiencing mixed or conflicting emotions or attitutes toward a particular situation, person, or decision, making it challenging to choose or commit to a specific course of action', 'yTerm': '', 'yDesc': 'Uunguciicaraq', 'speakers': ['Uunguciinaniwall’nalirrugglunicallminek', 'yugmek', 'wall’pillerkaminek', 'caperrnarilukucucukillerkaqwall’caqatallerminek.'], 'resourceID': '4'}, {'id': '80', 'eTerm': 'Openness', 'eDesc': 'Willing to accept and consider new ideas, perspectives, or experiences', 'yTerm': '', 'yDesc': 'Allakaukinailnguq', 'speakers': ['Ciuniuriyugngaluniumyuartuuteksugngaluki-llunutaratpillerkat', 'qailluntangvaumallrit', 'wall’callrit.'], 'resourceID': '4'}, {'id': '81', 'eTerm': 'Hesitation', 'eDesc': 'A temporary pause or delay in decision-making or action, often stemming fom uncertainty, doubt, or lack of confidence in choosing the best course of option', 'yTerm': '', 'yDesc': 'Nasperturyaraq', 'speakers': ['Pillerkiuringnaqkuniwall’caqataquniarulaiqerluniwall’qariqerrluni', 'ancurtuami', 'asguranakngamiu', 'wall’ellminekkemyukenrilamicucukinritnayukluniassinranek.'], 'resourceID': '4'}, {'id': '82', 'eTerm': 'Coping Strategies', 'eDesc': 'Ways people deal with and manage stress, challenges or difficult emotions. These can include various actions, thoughts, or behaviors that help people navigate tough situations', 'yTerm': '', 'yDesc': 'Qaillun Auluksaurcugngariyaraq', 'speakers': ['Yuutqaillunaulukitullratumyuamunarcarillret', 'cakviurutet', 'wall’caperrnarqellriitumyuarniurutet.Ilaklukiayuqenrilnguutcallrit', 'umyuartuutet', 'wall’yuutikayuutaitqaillunayagturallerkaatnuncakviungermeng.'], 'resourceID': '5'}, {'id': '83', 'eTerm': 'Healing', 'eDesc': 'The process of becoming healthy and whole again. It often involves recovery and improvement after a period of illness, trauma, or distress. ', 'yTerm': '', 'yDesc': 'Mamyaraq', 'speakers': ['Calricaraqtamalkuurcaraq-llu.Aturnarqelartuqutumariyaraqassiriinallerkaq-llunaulluurraarluni', 'umyuaqakngirterrarcelluku', 'wall’arenqialliurraarcelluku.'], 'resourceID': '5'}, {'id': '84', 'eTerm': 'Support', 'eDesc': 'Assistance, encouragement, or comfort provided by others, such as friends, family, or a community. Support can be emotional, practical, or both', 'yTerm': '', 'yDesc': 'Cingumayaraq', 'speakers': ['Allatikayurluku', 'cingumaluku', 'wall’qarulluku', 'ukutunyugnikekngat', 'ilait', 'wall’nunalgutaita.Cingumayugngauqumyuarakun', 'aipaqluku', 'wall’tamarkegenka.'], 'resourceID': '5'}, {'id': '85', 'eTerm': 'Harm Reduction', 'eDesc': 'An approach focused on reducing  the risks of certain behaviors or conditions, without completely stopping all the behaviors themselves. Small changes over time can have major long-term effects.', 'yTerm': '', 'yDesc': 'Ikgelicarluku Akngirun', 'speakers': ['Ikeglingnaqlukiaarnarqellriitayuquciiwall’uitallra', 'tau͡gaamtamalkuitaarulaircetevkenakiaarnarqellriitatuqekngai.Ikgenakicimiryaraitcakviurnarqelartutak’anun.'], 'resourceID': '5'}, {'id': '86', 'eTerm': 'Habits', 'eDesc': 'Consistent, often unconscious, behaviors that people develop throughout their lives. Habits can be both positive and negative, influencing daily routines and lifestyle choices', 'yTerm': '', 'yDesc': 'Piuryarat', 'speakers': ['Cimiyuinateng', 'amllerqunekelpeksuunaku', 'piciryaraityuutpiciryaraksagutellrityuucimegni.Piciryaratassiryugngautwall’assiicugngaut', 'agtuumalukicayaraityuuyarait-llu.'], 'resourceID': '5'}, {'id': '87', 'eTerm': 'Curable', 'eDesc': "When an illness is curable, it means that there is a treatment or intervention that can completely get rid of the illness. Imagine it like fixing a problem so that it goes away permanently, like taking antibiotics for a bacterial infection, once the treatment is successful, the illness is gone, and you don't have to worry about it coming back.", 'yTerm': '', 'yDesc': 'Mamyugngalria', 'speakers': ['Naulluunmamyugngalriarukuni', 'kangingqerciquqyuungcaryugngaluniwall’naulluunarulaivkangnaqlukucatairutlerkaanuntamalkuan.Tangrruarlukukitugillerkaaarenqiallugutemayagniartuqtaqluni', 'iinrukitellriatunpupikpitekluku.Iinrukcalikuninaulluuncatairuciiquq', 'peng’garnairulluni-llutainqigtellerkaanek.'], 'resourceID': '5'}, {'id': '88', 'eTerm': 'Treatable', 'eDesc': 'When an illness is treatable, it means that there are ways to manage or alleviate the symptoms of the illness. But it may not be possible to get rid of it completely or permanently.  Think of it like managing a chronic condition, such as diabetes. With ongoing treatment and lifestyle adjustments, you can control the symptoms and live a healthy life, but the condition might not go away entirely', 'yTerm': '', 'yDesc': 'Assiriyugngalria', 'speakers': ['Naulluunassiriyugngalria', 'auluksugngaciquqwall’ikegliyugngaciquqtamananaulluun', 'tau͡gaamtamarmicatairucesciigaciiqngatuq.Umyuaqlukuauluknarqellraak’anunnaulluun', 'saarralissiyaalriatunauktequq-llu.Yuungcarturaqunicaliyuuciqkitugareskuni', 'auluknarqelarciquqcaliyuuluaqernaqluni', 'tau͡gaamtaunanaulluuntamarmiassiringaituq'], 'resourceID': '5'}, {'id': '89', 'eTerm': 'Informal Supports', 'eDesc': 'Personal assistance and help that people receive from friends, family, or social networks', 'yTerm': '', 'yDesc': 'Allat Cingumastet', 'speakers': ["Yukikayurcellunicaliikayungqerrluniyugnikek'ngaminek", 'ilaminek', 'wall’allanekikayuritulinek.'], 'resourceID': '6'}, {'id': '90', 'eTerm': 'Community Resources', 'eDesc': 'Services, organizations, or facilities available within a community that provide support, assistance, or information to residents. These resources can include healthcare services, community centers, educational programs, and more. ', 'yTerm': '', 'yDesc': 'Nunaitni Ikayungcarviit', 'speakers': ['Kevgiurutet', 'quyungqalriitikayurtet', 'wall’caliviitpaivngalriitnunanicingumasteńguluteng', 'ikayuriluteng', 'wall’nallunairilutengyugnun.Makutikayuutetilangqerrsugngautcalricaramkevgiuriyaraanek', 'nunatquyurrvigkaatnek', 'elitnauryaranek', 'allanek-llu.'], 'resourceID': '6'}, {'id': '91', 'eTerm': 'Protective Factors', 'eDesc': "Parts of a person's life or environment that increase their resilience and help them manage stress and difficulties. They contribute to a person's well-being and can act as a buffer against stressors.", 'yTerm': '', 'yDesc': 'Qaunqiyarat', 'speakers': ["Yuucimiliinwall’avatiinquyigikanircet'laraapinirikanircellukuikayurluku-lluauluklukuumyuarniuruncaperrnarqellriit-llu.Ikayuutelartutyuumcalricaraanuncayailkucilriatun-lluayuqlukuumyuarniurutkanun."], 'resourceID': '6'}, {'id': '92', 'eTerm': 'Risk Factors', 'eDesc': "Parts of a person's life that increase the likelihood of negative outcomes or problems", 'yTerm': '', 'yDesc': 'Aarnarqellriit', 'speakers': ['Yuumyuucianiliinarcarilukiassinrilnguutwall’arenqiallugutait.'], 'resourceID': '6'}, {'id': '93', 'eTerm': 'Treatment Plan', 'eDesc': "A detailed and structure strategy developed by healthcare professionals to address an individual's specific health or behavioral issues. It outlines the intended interventions, therapeutic approaches, and goals to achieve the desired outcomes", 'yTerm': '', 'yDesc': 'Yuungcallerkam Pillerkiuraa', 'speakers': ['Iinrivigmicalistetayagnillritapertuumanqegcaaraumalriaatuyunarqellria-llupillerkiuraqcaliaqsuglukuyuumcalricaraawall’arenqiallugutii.Pillerkiulartuqikayullerkaanek', 'qaillunassiringcallerkaanek', 'egmirutekaanek-llupiyuutiinunakellerkaanek.'], 'resourceID': '7'}, {'id': '94', 'eTerm': 'Goals', 'eDesc': 'Broad, overarching statements that describe the desired results or changes a person aims to achieve. In the context of a treatment plan, goals provide a general direction for progress and improvement', 'yTerm': '', 'yDesc': 'Egmirutet', 'speakers': ['Qanerniarutetaperturilutengiqukanekwall’cimirlukiyuumpiukekngai.Assirillerkampillerkiuraani', 'egmirutekiulartutassirillerkamtungiinuncaliutumarillerkamun.'], 'resourceID': '7'}, {'id': '95', 'eTerm': 'Objective', 'eDesc': 'Specific, measurable, and time-bound steps or actions designed to achieve the broader goals outlined in a treatment plan. Objectives break down the goals into smaller, manageable components, making it easier to track progress and success.', 'yTerm': '', 'yDesc': 'Picirkiurun', 'speakers': ['Apertuumanqegcaarluni', 'cuqcugngaluku', 'caliapertuutettaqlerkiurangqerrlutengwall’egmirutekaitatuyunaqlutengyungcaryaraanpillerkiuraini.Egmirutekatpicirkiurutetgunatuyunarilartutikeglillritgun', 'auluksunarillritgun', 'qacignarivkarlukicuqtellerkaitassiriinaryaramuncalielluarillerkamun.'], 'resourceID': '7'}, {'id': '96', 'eTerm': 'Informed Consent', 'eDesc': 'Autonomy is closely tied to the concept of informed consent. Before any medical procedure or treatment, healthcare providers should provide patients with any available information about the types of help they are suggesting, including potential risks, benefits, and alternatives. ', 'yTerm': '', 'yDesc': 'Nallunrirceciyaraq', 'speakers': ['Ellminekataniuryaramayuqeqapigtanallunrirceciyaraq.Iinrivigmicavailgatguwall’yuungcarpailgatgu', 'calricariurtetnallunaircetarkaugaityuungcarvigtellriitnallunaircellukiayuqenrilngurnekikayuutekaitnek', 'ilalukiaarnarqutaitnek', 'ikayuutekaitnek', 'allanek-llupiyugngallritnek.'], 'resourceID': '8'}, {'id': '97', 'eTerm': 'Respecting Preferences', 'eDesc': 'Healthcare professionals should respect and consider the individual preferences and values of their patients. They must recognize that people may have diverse cultural, religious, or personal beliefs that influence their healthcare decisions.', 'yTerm': '', 'yDesc': 'Qigcikluki Piyuutait', 'speakers': ['Calricariurtetqigcikarkaugaitcaliumyuartuuteklukiiinrivigtellriitpiyuutaitarcaqakekngait-llu.Elitaqumaarkaugaityuutayuqenrilngurnekyuuyarangqellrit', 'agayumaciit', 'wall’ukverutaitcalricarampillerkiuryaraantungiinun.'], 'resourceID': '8'}, {'id': '98', 'eTerm': 'Shared Decision-Making', 'eDesc': 'Autonomy encourages providers to work together with their patients for all decision making rather than choosing what should be done about any identified problems alone. ', 'yTerm': '', 'yDesc': 'Ikayuqulluteng Pillerkiuriyaraq', 'speakers': ["Ellminekataniuriyaramcingumalaraicalricariurtetcalillgutkesqumalukiiinrivigtellriitilaklukipillerkiurillerkaitkiinganarenqiallugutaitauluklerkaitangvagpek'naku."], 'resourceID': '8'}, {'id': '99', 'eTerm': 'Confidentiality', 'eDesc': 'Respecting autonomy includes ensuring the confidentiality of patient information. Patients should feel confident that their personal health information will be kept private unless they give clear permission for it to be used in specific ways.', 'yTerm': '', 'yDesc': 'Qalarutkumaarkaunrilnguut', 'speakers': ['Qigcikiyaraqellminekataniuriyaramekilangqertuqqalarutkarkaunritellranekiinrivigtellriimnallunairutainek.Iinrivigtellriitkemyunakarkaugaitcalricaraatanallunairutaitqanrutkumaarkaunritellritnekapterraarpailganatuusqellukuqaillun.'], 'resourceID': '8'}, {'id': '100', 'eTerm': 'Refusal of Treatment', 'eDesc': 'Patients have the right to refuse medical treatment, even if healthcare providers believe it is in their best interest. This refusal should be respected, and alternative options or consequences should be discussed.', 'yTerm': '', 'yDesc': 'Yuungcaasqumanritlerkaq', 'speakers': ['Iinrivigtellriitpiyunarqucingqertutciuniunricugngalukiyuungcaryarateng', 'calricariurtetukvengraatkiassirnilukutaumun.Ciuniurinritleqqigcikumaarkauguq', 'caliqalarutkarkaugutallaggunyuungcallerkamekwall’qaillunpiciqellranekciuniurumanrilkanyuungcarrsuutekaa.'], 'resourceID': '8'}, {'id': '101', 'eTerm': 'Cultural Competence', 'eDesc': 'Autonomy recognizes the importance of cultural competence in healthcare. Healthcare providers should be sensitive to the cultural backgrounds of their patients and adapt their approach to treatment accordingly. ', 'yTerm': '', 'yDesc': 'Yuuyaram Atuuyugngallra', 'speakers': ['Ellminekataniuryaramelitaqumaaarcaqauciayuuyaraqcalricarami.Calricariurtetelpekumarkaugaityuuyaraatiinrivigtellriitcaliyungcarillermeggnunaturlukipinarqekan.'], 'resourceID': '8'}, {'id': '102', 'eTerm': 'Guardianship and Incapacity', 'eDesc': "In cases where a person lacks the capacity to make decisions for themselves, autonomy may involve appointing a legal guardian for them. Even in these situations, efforts should be made to understand and consider the individual's wishes and values.", 'yTerm': '', 'yDesc': 'Aulukiyaraq cali Casciigalnguq', 'speakers': ['Kinayukpillerkiurciigalkanellminek', 'ataniuryaramellminekilaksugngaaqanercetaarvigkunaulukestekillukutauna.Wat’nangraan', 'taringnarqerkauguqcaliumyuaqlukuyuumpiyuutiiarcaqakekngai-llu.'], 'resourceID': '8'}, {'id': '103', 'eTerm': 'Educating and Empowering Patients', 'eDesc': 'Autonomy involves empowering patients with information and resources to actively participate in their healthcare decisions. This includes providing education about their medical conditions, treatment options, and self-management strategies.', 'yTerm': '', 'yDesc': 'Elicungcarluki Atanrurtelluki Inrivigtellriit', 'speakers': ['Ellminekataniuryaramilakaainrivigtellriitpiyunarqucilirlukiilagaucugngallritnallunairutnekikayuutekanek-llupillerkiurillratnicalricaramegnek.Ilaklukielicungcarlukinaulluutaitnek', 'yuungcarrsuutekaitnek', 'ellaitnekpillerkiuraitaauluksaraitnek-llu.'], 'resourceID': '8'}, {'id': '104', 'eTerm': 'Precontemplation', 'eDesc': 'The person is not yet considering change. They may be unaware or in denial of a need for any change.', 'yTerm': '', 'yDesc': 'Cimirngaicuklukuaq', 'speakers': ["Yukumyuarturpek'nanicimillerkaminek.Aipaagnitayimaelpekenritaawall’cimirnarqenricuklukuarluni."], 'resourceID': '9'}, {'id': '105', 'eTerm': 'Contemplation', 'eDesc': 'The person is aware of the need for change but is undecided. They may weigh the pros and cons of changing.', 'yTerm': '', 'yDesc': 'Umyuartuuteksaraq', 'speakers': ['Yuumelpeklukucimirnarqellnitau͡gkennalirruggluni.Yuvriryugngaatcimillerkamassillraassinritellra-llu.'], 'resourceID': '9'}, {'id': '106', 'eTerm': 'Preparation', 'eDesc': 'The person has decided to make a change. They may begin planning and taking small steps toward change.', 'yTerm': '', 'yDesc': 'Upcaraq', 'speakers': ['Yukumyuangellruuqcimiryugluni.Ayagnirilunipillerkiuramekcimirnalunicukaunani-lluayagniqcaarlunicimillerkaminun.'], 'resourceID': '9'}, {'id': '107', 'eTerm': 'Action', 'eDesc': 'The person actively engages in behaviors to make the change they want. This stage involves the most visible and noticeable changes in behavior.', 'yTerm': '', 'yDesc': 'Egmirulluku/Ayagnirluku', 'speakers': ['Yuumayuquciniegmirullukucimingnaqluniayuqsullerminun.Unacimiryaraqtangerrnarqellriaruuqelitaqnaqluteng-llucimirturallraayuquciaggun.'], 'resourceID': '9'}, {'id': '108', 'eTerm': 'Maintenance', 'eDesc': 'The person works to keep the changes made during the action stage. This stage involves preventing relapse and consolidating gains.', 'yTerm': '', 'yDesc': 'Aulukuuryaraq', 'speakers': ['Yuumcaliaquurlukucimirturallnicimirtuuryaramnalliini.Mat’umcimirtuuryaramcaliaqaaataamayuqelallmitunpinritengnaqsaraqcalielluatmunayangnaquurluni.'], 'resourceID': '9'}, {'id': '129', 'eTerm': "Hi I'm your nurse, my name is _______", 'eDesc': 'Do you need anything? \nWhat do you need?', 'yTerm': '', 'yDesc': 'Waqaa, Iinriurtekarpenga, atqa _______-aaruuq/auguq', 'speakers': ['Cayugtuten-qaa?(Thiswordcanbeusedforbothquestion.)'], 'resourceID': '12'}, {'id': '130', 'eTerm': 'How can I help you?', 'eDesc': 'Where is your pain? \nHow much does it hurt? \nWould you like pain medication? \nWould you like an ice pack or hot pack?', 'yTerm': 'Your next dose of pain medicine will be at...(time)', 'yDesc': 'Qaillun ikayuryugngasia?', 'speakers': ["Nauggunakngiasit?Qaill'pitalriamekakngirnarqa?Iinruyugtutenakngianritlerkanpitekluku?Qatugasuuteryugtuten-qaakumlamekwall'puqlamek?"], 'resourceID': '12'}, {'id': '131', 'eTerm': 'Are you in pain?', 'eDesc': "I can't give you water\nYou're not allowed to eat or drink \nWhat kind of juice do you want?", 'yTerm': "You're on a fluid restriction and can have (1 or 1.5 Liters) a day\n\nFluid restriction: The doctor orders a set amount of fluid intake by mouth per day for when someone has heart failure or renal issues. The nurse keeps track of everything liquid that the patient drinks (ie, coffee, water, juice, soup) & often has to negotiate with the patient about how much they've already had / what they want to drink and when, to stave off thirst but maintain within the allotted amounts", 'yDesc': 'Akngiaguten-qaa? Enllugturiuten-qaa?', 'speakers': ['Merkicescigatamken', "Neresciigatutenwall'merciigatuten.Cakucimekjuice-aryugcit?"], 'resourceID': '12'}, {'id': '132', 'eTerm': 'Do you want water?', 'eDesc': "We'll reposition you\nDo you want to be repositioned?\nAre you warm enough?\nWould you like a blanket?\nHow is the temperature in the room?\nDo you want pillows?\nWhat can I do to make you comfortable?", 'yTerm': 'Is that better?', 'yDesc': 'Meqsugtuten-qaa?', 'speakers': ["Nugtakaninqigteqaataramteggen.Nugtakaninqigcesquten-qaa?Qerrutenrituten-qaa?Uligkicesquten-qaa?Puqliimat'umcangaksiu?Putuskaryugtuten-qaa?Casqesiaarenqilillerkarpettungiinun?"], 'resourceID': '12'}, {'id': '133', 'eTerm': 'Are you comfortable?', 'eDesc': "We don't want you to fall\nIn the ICU, you need to have staff with you to walk\nYour muscles are weak and you could hurt yourself if you try to get out of bed on your own\nPhysical Therapy will come work with you", 'yTerm': 'Do you want to go for a walk?\nDo you want to sit in a chair?\nI\'m going to grab a coworker and we\'ll help you\nDo you want to get back in bed?\nWe can walk down the hallway together\nHold my hand\nI\'ll help you\nWait for me\nI\'ll be right back\n\nPhysical Therapy / PT: in ICU setting, comes during daytime primarily on weekdays; helps ""mobilize"" patients / the team helps figure out which assistive devices (canes, walker, etc) are most appropriate for people to get out of bed with. If someone has been sedated / unconscious for a while, we typically wait until PT comes to get them out of bed for the first time, if their muscles are deconditioned / if they haven\'t used their muscles in a while', 'yDesc': 'Arenqigtuten-qaa?', 'speakers': ['Igcesqumanritamteggen.ICU-mi', 'calistemekmalingqerrarkaugutenpiyuakuvet.Temevetyualuikayuitutmaktengnaqkuvet-lluelpenekakngircuartuten.Kayungcaristemullaglutenkayungcaryarturceciiqaaten.'], 'resourceID': '12'}, {'id': '134', 'eTerm': "You can't get out of bed", 'eDesc': '""Call don\'t fall"" - a phrase in hospital rooms\nYou can call me for anything\nWe have time for you\nWe want to care for you, let us know what you need', 'yTerm': '', 'yDesc': 'Inglerpenek atrarciigatuuten', 'speakers': ['""Qayagaurlutenigcaqunak""iinrivigmiqaneryarauguq.Qayagauryugngaarpengacayukuvet.Sass\'angqertukutelpenun.Auluksugamteggen', 'nallunrirceskikutcayukuvet.'], 'resourceID': '12'}, {'id': '135', 'eTerm': "Here's your call bell if you need me", 'eDesc': "Do you need to poop or pee?\nWe're going to clean you up\nWe're going to help you onto a bedpan\nYou have a catheter that's taking away your urine\nIf you need to pee, call me\nHere is your urinal\nCan you turn in the bed by yourself? Or do you want our help?", 'yTerm': 'Turn away from me\nTurn towards me\nGrab onto the siderails\nPut your hands across your chest\nGive yourself a hug\nDo you want music playing?\nWhat kind of music do you like?\n\n""Catheter: can refer to any medical device that goes into the patient (ie, IV catheter, foley catheter, central catheter...)\nFoley catheter / urinary catheter: """"foley"""" is a brand name that we shorthand to refer to """"urinary catheter;"""" urinary catheter is a tube that goes into urethra, takes away pee directly from bladder""', 'yDesc': 'Waniwa ikayuryukuuvet nallunaircuun kulukunaq', 'speakers': ["Anaqsugtutenwall'yuqercugtuten?Eruqataramteggen.Ingelremyuqervianunelliqataramteggen.Qurrsuutenqiluruangqertuqteq'urpetayagtuursuutekaanek.Yuqercukuuvet", "qayagauqai.Waniwayuqervin.Elpenek-qaanugtarcugngauteninglerpeni?Wall'ikayuusqutenwankutnun?"], 'resourceID': '12'}, {'id': '136', 'eTerm': 'Do you need to go to the bathroom?', 'eDesc': '', 'yTerm': '', 'yDesc': 'Yuqervigcugtuten-qaa?', 'speakers': [], 'resourceID': '12'}, {'id': '137', 'eTerm': 'Sepsis', 'eDesc': 'Sepsis is like, how when you get hurt, and your body rushes a bunch of protective fluid to where the injury is. The blood vessels expand and the area gets swollen, so that your body can repair the area. Sepsis is when an infection triggers the impulse to protect the body and causes swelling everywhere - all of your blood vessels expand. It can get out of control fast. Blood pressure drops and your vital signs go out of wack, which, without treatment, can cause your kidneys, brain, and liver, to be deprived of essential blood flow. Without treatment, organ failure and death can occur.', 'yTerm': 'Science / Pathophysiology:\nSepsis is characterized by an infection that enters the blood stream and causes vital sign changes, like: high temperature, low blood pressure, high heart rate, high respiratory rate / rapid breathing. It is usually also accompanied by abnormal lab findings, in particular high or very low white blood cell count. \n\nCommon Treatments / Care:\nThere are protocols for sepsis, including:\n\n-Draw Blood Cultures & other labs\n-Secure IV access\n-Give fluid IV\n-Give antibiotics\n-Treat abnormal vital signs (ie, if they\'re feverish, give tylenol / ice packs, get their blood pressure up, give oxygen if they\'re struggling to breathe)\n\nIf the person continues to get worse, treatment can include:\n-Pressors\n\nRelevant Definitions:\n""-IV: intravenous. A tiny tube that goes into the vein, that allows us to give medications and sometimes draw blood\n-Antibiotics: medications that fight infections\n-""""Fluid"""": specific formulas of saltwater that we give through IV\'s to treat lots of different kinds of medical issues / keep someone hydrated\n-Pressors: Also called Vasopressors, refers to a class of drugs that squeezes the blood vessels so as to increase blood pressure. There are several medications in this category, but are generally just referred to as pressors outside of detailed communication between healthcare providers""', 'yDesc': '1. Kilinrem siissia augmun iterluni alingnarqellriaruluni tuquciyugngaluni puvqercirituli.                   2.  Naullutem ciissian puvqercetellra augem avayai.', 'speakers': ['Sepsis-aaqwatenayuquq', 'akngirtaqaavet', "temvet-llumer'iquyurrlutengkitugingnaqlukuakngiruuten.Augemnutngassutaiqerrurlutengavatii-llupuvqercelluku", 'temevetassiringcarniaraiavatii.Kilinremayagniraqakumamtengnaqlukutemapuvivkarlukutemiitamalkuan.Tamarmeng-llutememavayaipuvqerrluteng.Arcarillracukayugngauq.Augem-llunutngaarallraaciqsigiluni.Qailluqerrluni-lluyuuciq', 'aulukumanrilkata', 'yungcaumanrilkunitartuq', 'pateq', 'tenguk-llunuqlitengciqutaugmek.Yungcaumanrilkuneng', 'cakunglluutcalinrirciquttuqunaqluteng-llu.'], 'resourceID': '13'}, {'id': '138', 'eTerm': 'Pneumonia', 'eDesc': "An infection of the lungs. It can interfere with oxygen getting into the blood and make it hard to breathe. It can cause organ failure if it either becomes a systemic infection (for ex, sepsis), or if oxygen is unable to get into the blood to the point that organs aren't getting oxygenated (for ex, COVID pneumonia). ", 'yTerm': 'Science / Pathophysiology:\nIn pneumonia, the areas of the lung that typically allow air to enter the body and interface with the blood stream become filled with phlegm and/or fluid. Pneumonia causes shortness of breath, changes seen on X-ray imaging, cough, congestion, and potentially other vital sign changes / changes in the person\'s disposition (ie, fatigue / unresponsiveness / organ failure).\n\nCommon Treatments / Care:\nOxygen\nAntibiotics (IV or oral/pills)\nSupportive Care\nIntubation: in which the doctor puts a tube into someone\'s mouth & trachea, to create an airway through which we can control someone\'s breathing using an ambu-bag or ventilator. During this time the person will receive tube feeds for nutrition\nVentilator: a machine that controls breathing\nIf the person is unable to get off the vent / be extubated, then they might be trach\'d and peg\'d\nTracheostomy: a hole in the throat that gives direct access to trachea, so that someone\'s breaths can be delivered directly by medical professionals long term\nTrach often goes with """"Peg"""", or G-Tube / Gastrostomy tube, which is a tube into the stomach so the person can receive nutrition\n\nRelevant Definitions:\n""""Oral"""": by mouth?? So if we\'re saying """"oral medication,""" we mean a medication that\'s taken by mouth, or like, in a different context, if we say """"oral hygeine,""" we mean the hygiene of the mouth\n-Supportive Care: Really means anything we do that supports the specific situation of the body of the individual in front of us. Can mean: pain management, fluids, ventilators, pressors, etc\n-Tube feeds: a liquid mixture that we put through a feeding pump so people can get calories\n-Vent: same as ventilator\n-Extubation: taking the breathing tube out\n', 'yDesc': 'Patsaqaq', 'speakers': ["Pugtautemkumlaqertellra.Iterciigalivkaryugngalukuoxygen-aaqaugmunanerniqnarivkarluku.Cakunglluutcalinrircecugngalukinaulluutngureskan(sepsis-aatun)wall'oxygen-aqiterciigalikanaugmuncakunglluut-llucalisciigalivkarlukioxygen-ailata(COVID-aaggun", 'patsaqercaraq).'], 'resourceID': '13'}, {'id': '139', 'eTerm': 'Renal Failure / Kidney Failure / Renal Disease', 'eDesc': "The kidneys get rid of water, so if they're not working, fluid backs up throughout the body. The person stops peeing. The extra burden of fluid can cause swelling everywhere (esp in sepsis) and the toxins and electrolytes that the kidneys normally get rid of stay in the body. So, labs can get super out of wack, and if the person doesn't get these things out of their body, they can die. We monitor electrolytes frequently in order to make sure the lab values don't get too wacky.", 'yTerm': 'Science / Pathophysiology:\nCan happen because of an acute event, like sepsis - the blood pressure is so low that the kidneys don\'t get blood flow, and stop working - or from chronic disease, like diabetes - the persistently elevated blood sugar damages the blood vessels\n\nCommon Treatments / Care:\n-Diuresis: an intervention to help kickstart the kidneys into working. Diuretics (""water pills"") help get rid of fluid and, as fluid is pulled out of the body, electrolytes & other toxins go with it\n-Dialysis\n\nRelevant Definitions:\n-Diuresis: producing urine. Pills & IV medications can help produce urine\n-Dialysis: a machine that mimics the function of the kidney. There are several kinds of dialysis, including hemodialysis, which people can do outpatient, generally 3 x a week, and can also do if there\'s an acute event & they\'re in the hospital (ie, overdose), and CRRT - a continuous form of dialysis that can only happen in the ICU. Dialysis is run by nurses and a nephrologist\n', 'yDesc': 'Tartuq Calinrirluni/ Tartuq Calinrirluni/ Tartuum Naulluutii', 'speakers': ["Tartummer'ayagciquralaaraa", "tua-i-llucalinrilkunekmer'ungalnguutayagviirrlutengtememi.Yuk-lluqurrsuirulluni.Mer'ungalnguuttememipuvivkaryugngaatem'iitamalkuan(arcarqerlukunaullluutemsiissiaaugmunitraqan-sepsis)calituqunarqellriityuunqegcessuucet-llu?(electrolytes)ayagcetetukaittartumuitaurlutengtememi.Augillritayuquciimegteggunayuqenrirluteng", 'tamakutantenrilkatkiyuumtemiinek', 'tuquyugngalunitauna.Kelluquralaraputkesianekelectrolyte-aitaugitpaqtellritayuquciicetunuitatassiirturluki.'], 'resourceID': '13'}, {'id': '140', 'eTerm': 'Congestive Heart Failure (CHF)', 'eDesc': "Every time your heart beats, it pushes blood throughout your body. Heart failure is when the mucles of the heart aren't able to push hard enough to get blood through; this causes blood to back up. ", 'yTerm': "Science / Pathophysiology:\nCHF is a chronic process over time & has significant impact on people's everyday lives, esp r/t fatigue, shortness of breath, and reduction in activity. People with CHF are often so tired and out of breath that it becomes hard for them to tolerate any kind of activity. When the heart isn't pumping fully, it can cause fluid to back up into the lungs (which is what causes shortness of breath) and/or legs, causing leg swelling. \n\nCommon Treatments / Care:\n-Diuresis, to get rid of the burden of fluid on the heart\n-Fluid restriction\n-Medications to help the heart pump stronger\n-Supportive Care: meds to keep blood pressure in range, help out kidneys if they're having trouble, oxygen if lungs are struggling, etc\n\n", 'yDesc': 'Ircaquq ellminek nutngaurarciigaliluni (CHF)', 'speakers': ['Ircaqunnutngaaqami', 'augmekayagceciilartuqtemevnun.Ircaqumnutngaurallratukniarutngaqaamiyualuiircaquumcaknaanarituuqanciurallraaugmek;waten-llupiaqamiauknatvarviirutlartuq.'], 'resourceID': '13'}, {'id': '141', 'eTerm': 'Withdrawal (Alcohol withdrawal, can also happen with street drugs, and can also happen because of the sedating medications we give in the ICU)', 'eDesc': "When someone's body isn't getting the substance it's used to, they can become very delirius and agitated. For alcohol, from day 3- day 10 without alcohol is the potentially life-threatening period. We treat their symptoms of withdrawal based on how severe symptoms are.", 'yTerm': "Science / Pathophysiology:\nThe receptors that alcohol & other drugs attached to are now free, which causes cravings and physical withdrawal symptoms. Most hospitals use a scale like this one to measure withdrawal symptoms. The higher the score, the more likely it is the person might have life-threatening symptoms, such as seizures. \n\nCommon Treatments / Care:\nWe give medications based on the symptoms - so if someone is having very severe withdrawal, they might need so much sedation that they can't keep their mouth open / they're not awake enough to cough. But, if their withdrawal is mild, then we only have ot give them small doses, and they might be otherwise appropriate. Treatment for withdrawal is all considered supportive care; it really depends on the situation.", 'yDesc': "Aturturarraarluni camek atuyuirtellran ayuqucia temem elisngakiinek unangyuirucaaraam ayuqucia (revisit) (Taangarturatulim temii taanganritqallran ayuqucia temii taangamek atunrillran    iinrurrluut ilakluki, cali qavarcetaat/qinuirucetaat iinruitnek piicesciigacugngaluni, iinrukit'laqngamtenek ICU-mi)", 'speakers': ['Kiayuumtemiiunangenritaaqancamekelisngakiinektemiin', "usviirtellriatunayuqliriilartuqeqnayukaryuka'ariiluni-llu.Taanganritaqamiyuk3-10ernerniyuucimunalingnarqellriarulartuq.Yungcalararputtaqesciigalutaitangvaglukiqaillunalingnarqucii."], 'resourceID': '13'}];
